template<class T>struct Com{
    T* p=nullptr;Com()=default;Com(const Com&)=delete;Com& operator=(const Com&)=delete;
    Com(Com&& other) noexcept:p(other.p){other.p=nullptr;}Com& operator=(Com&& other) noexcept{if(this!=&other){reset();p=other.p;other.p=nullptr;}return *this;}
    ~Com(){reset();}void reset(){if(p)p->Release();p=nullptr;}T** out(){return &p;}
};
void check(HRESULT code,const char* why){if(FAILED(code))throw std::runtime_error(std::string("NG-E-FIELD-VISUAL-GPU: ")+why);}
int brick(int cell){return cell/16-(cell%16<0);}
std::uint32_t generation(std::uint32_t old){return old==UINT32_MAX?0:old+1;}
struct Key{ChannelId channel=0;Cell brick{};bool operator<(const Key& b) const{return std::tie(channel,brick.x,brick.y,brick.z)<std::tie(b.channel,b.brick.x,b.brick.y,b.brick.z);}};
using SourceKey=std::pair<std::string,std::uint64_t>;
struct PageRecord{std::int32_t x,y,z;std::uint32_t channel,resource,padding[3]{};};
struct WorkPage{std::int32_t x,y,z;std::uint32_t channel,first,count,maximum,merge;};
struct Row{std::int32_t minX,minY,minZ;std::uint32_t descriptor;std::int32_t maxX,maxY,maxZ;std::uint32_t low,high,dimX,dimY,padding=0;};
static_assert(sizeof(PageRecord)==32&&sizeof(WorkPage)==32&&sizeof(Row)==48,"GPU visual WF ABI changed");
D3D12_RESOURCE_DESC description(std::uint64_t bytes,bool writable){D3D12_RESOURCE_DESC d{};d.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;d.Width=bytes;d.Height=1;d.DepthOrArraySize=d.MipLevels=1;d.SampleDesc.Count=1;d.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;d.Flags=writable?D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS:D3D12_RESOURCE_FLAG_NONE;return d;}
std::uint64_t allocation(ID3D12Device* device,std::uint64_t bytes,bool writable=false){const auto d=description(bytes,writable);return device->GetResourceAllocationInfo(0,1,&d).SizeInBytes;}
void buffer(ID3D12Device* device,Com<ID3D12Resource>& out,std::uint64_t bytes,bool writable){D3D12_HEAP_PROPERTIES p{};p.Type=writable?D3D12_HEAP_TYPE_DEFAULT:D3D12_HEAP_TYPE_UPLOAD;p.CreationNodeMask=p.VisibleNodeMask=1;const auto d=description(bytes,writable);check(device->CreateCommittedResource(&p,D3D12_HEAP_FLAG_NONE,&d,writable?D3D12_RESOURCE_STATE_COMMON:D3D12_RESOURCE_STATE_GENERIC_READ,nullptr,IID_PPV_ARGS(out.out())),"Create snapshot buffer");}
void upload(ID3D12Resource* resource,const void* data,std::size_t bytes){void* mapped=nullptr;D3D12_RANGE none{0,0};check(resource->Map(0,&none,&mapped),"Map snapshot metadata");if(bytes)std::memcpy(mapped,data,bytes);D3D12_RANGE written{0,bytes};resource->Unmap(0,&written);}
