    struct Source{GpuLease writer;std::shared_ptr<GpuLocalProjection> projection;GpuProjectionBindings binding;std::uint64_t epoch=0;Tick publishTick=0;};
    struct Checkpoint {std::vector<LeaseSlot> leases;std::map<SourceKey,Source> sources;bool committed=false;};
