    std::vector<Channel> catalog;GpuVisualLimits limits;GpuLocalGrid grid;std::vector<LeaseSlot> leases;std::map<SourceKey,Source> sources;
    std::vector<std::shared_ptr<Snapshot>> snapshots;std::shared_ptr<Snapshot> current;std::vector<std::weak_ptr<GpuVisualView>> views;
    std::map<SourceKey,SourceView> committedStates;
