    if((s.committed&&tick<=s.committedTick)||tick==UINT64_MAX)return fail(PublishResult::PastTick,"cannot amend committed tick");if(old==s.sources.end()&&s.sources.size()>=s.limits.maxSources)return fail(PublishResult::CapacityExceeded,"source record budget");
